ALLOWED = {
    "REQUESTED": {"SENT"},
    "SENT": {"SUCCEEDED", "FAILED", "UNKNOWN"},
    "UNKNOWN": {"SUCCEEDED", "FAILED", "MANUAL"},
}
def move(s, to):
    return f"{s}->{to} " + ("OK" if to in ALLOWED.get(s, set()) else "거절")

# 출력
# REQUESTED->SENT OK
# SENT->UNKNOWN OK
# UNKNOWN->SUCCEEDED OK
# SUCCEEDED->FAILED 거절
# REQUESTED->SUCCEEDED 거절

ours = {"T1": 50000, "T2": 120000, "T3": 30000, "T4": 7000}
bank = {"T1": 50000, "T2": 12000, "T4": 7000, "T5": 9900}
for k in sorted(ours.keys() | bank.keys()):
    a, b = ours.get(k), bank.get(k)
    if a != b:
        why = "은행에 없음" if b is None else "우리 원장에 없음" if a is None else "금액 다름"
        print(k, a, b, why)

# 출력
# T2 120000 12000 금액 다름
# T3 30000 None 은행에 없음
# T5 None 9900 우리 원장에 없음
